const unsupported = (id:string) => ['slack','teams','microsoft-teams','whatsapp','telegram'].includes(canonical(id));
const enc = encodeURIComponent;
const failMessage = (e: any) => e?.message || String(e);
const listResult = <T,>(value: any, key: string): T[] => Array.isArray(value) ? value : value?.[key] || value?.items || [];
const itemResult = <T,>(value: any, key: string): T => value?.[key] || value?.item || value;
const canonical = (value: string) => (value || '').toLowerCase().replace(/[ _]/g,'-');
function matchesProvider(connection: Connection, provider: string) {
  const value = canonical(connection.provider || connection.name);
  if (provider === 'google-calendar') return value.includes('calendar');
  if (provider === 'wechat') return value==='wechat'||value==='wechat-sync';
  if (provider === 'teams') return value.includes('teams');
  if (provider === 'feishu') return value.includes('feishu') || value.includes('lark');
  return value === provider || value.startsWith(provider + '-');
}
function connectionFor(ctx: UIContext, provider: string) {
  if(provider==='wechat')return ctx.state.connections.find(c=>c.id==='wechat-sync-local');
  const matches=ctx.state.connections.filter(c=>matchesProvider(c,provider));
  return provider==='feishu'?ctx.state.connections.find(c=>c.id==='feishu-local')||matches.find(c=>c.status==='connected')||matches[0]:matches.find(c=>c.status==='connected')||matches[0];
}
async function testConnectionRequest(ctx:UIContext,provider:string,input:any,existing?:Connection) {
  if(provider==='feishu'||matchesProvider(existing||{id:'',name:provider,provider,type:'provider',status:'setup_required'},'feishu')){
    let local=ctx.state.connections.find(c=>c.id==='feishu-local');
    if(!local){
      try{local=itemResult<Connection>(await api.get('/connections/feishu-local'),'connection');}
      catch(e:any){if(e.status!==404)throw e;try{local=itemResult<Connection>(await api.post('/connections',{id:'feishu-local',name:'Feishu',provider:'feishu',type:'CLI',permissions:input.permissions||['read','draft','send'],config:input.config||{}}),'connection');}catch(conflict:any){if(conflict.status!==409)throw conflict;local=itemResult<Connection>(await api.get('/connections/feishu-local'),'connection');}}
    }
    return api.post<any>('/connections/feishu-local/test',{...input,provider:'feishu',type:local?.type||'CLI'});
  }
  return api.post<any>(existing?'/connections/'+enc(existing.id)+'/test':'/connections/test',input);
}
function relativeSync(date: any, t: Translate) {
  if (!date || Number.isNaN(new Date(date).getTime())) return t('Not yet synced','尚未同步');
  const min = Math.max(0,Math.floor((Date.now()-new Date(date).getTime())/60000));
  return min < 1 ? t('Last synced just now','刚刚同步') : min < 60 ? t(`Last synced ${min} min ago`,`${min} 分钟前同步`) : t(`Last synced ${new Date(date).toLocaleString('en-GB')}`,`上次同步 ${new Date(date).toLocaleString('zh-CN')}`);
}
function Icon({kind, size=18}:{kind:string;size?:number}) {
  const paths: Record<string,React.ReactNode> = {
    calendar:<><rect x="4" y="5" width="16" height="15" rx="2"/><path d="M4 10h16M8 3v4M16 3v4"/></>,
    plus:<path d="M12 5v14M5 12h14"/>,check:<path d="M5 12.5l4.5 4.5L19 7.5"/>,back:<path d="M15 5l-7 7 7 7"/>,
    file:<><path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><path d="M14 3v6h6"/></>,
    shield:<path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z"/>,chat:<path d="M4 5h16v11H9l-5 4z"/>,
  };
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[kind] || paths.plus}</svg>;
}
function ProviderIcon({provider,large=false}:{provider:{id?:string;letter:string;bg:string;color:string};large?:boolean}) {
  return <span className={'settings-provider-icon'+(large?' settings-provider-large':'')} style={{background:provider.id?'#FFFFFF':provider.bg,color:provider.color}}>{provider.id?<img src={'/brands/'+provider.id+'.svg'} alt="" width={28} height={28}/>:provider.letter}</span>;
}
function Status({status,t}:{status:string;t:Translate}) {
  const on = status==='connected';
  const error = ['error','failed','expired','auth_required'].includes(status);
  const label = status==='unsupported'?t('Not supported yet','暂不支持'):on ? t('Connected','已连接') : error ? t(status==='expired'?'Authorization expired':'Needs attention',status==='expired'?'授权已过期':'需要处理') : status==='testing' ? t('Testing','检测中') : status==='setup_required' ? t('Setup required','需要配置') : t('Not connected','未连接');
  return <span className={'settings-status'+(on?' settings-status-on':error?' settings-status-error':'')}>{label}</span>;
}
function Modal({title,children,onClose,busy=false}:{title:string;children:React.ReactNode;onClose:()=>void;busy?:boolean}) {
  const {t: uiText}=useI18n();
  const ref = useRef<HTMLDivElement>(null);
  useEffect(()=>{
    const previous = document.activeElement as HTMLElement;
    ref.current?.querySelector<HTMLElement>('input,textarea,select,button')?.focus();
    return ()=>previous?.focus?.();
  },[]);
  function keydown(e: React.KeyboardEvent) {
    if(e.key==='Escape' && !busy) onClose();
    if(e.key!=='Tab') return;
    const nodes = Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]') || []);
    if(!nodes.length)return;
    if(e.shiftKey && document.activeElement===nodes[0]){e.preventDefault();nodes[nodes.length-1].focus();}
    if(!e.shiftKey && document.activeElement===nodes[nodes.length-1]){e.preventDefault();nodes[0].focus();}
  }
  return <div className="settings-modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)onClose();}}><div className="settings-modal" role="dialog" aria-modal="true" aria-labelledby="settings-modal-title" ref={ref} onKeyDown={keydown}><div className="settings-modal-title"><h2 id="settings-modal-title">{title}</h2><button aria-label={uiText("Close")} className="settings-modal-close" onClick={onClose} disabled={busy}>×</button></div>{children}</div></div>;
}
function Markdown({text}:{text:string}) {return <>{text.split('\n').map((line,i)=><div key={i} className={line.startsWith('#')?'settings-markdown-heading':undefined}>{line || '\u00a0'}</div>)}</>;}

export default function Settings({ctx,section,route}:{ctx:UIContext;section?:string;route?:string}) {
  const t: Translate = (en,zh)=>ctx.state.settings.identity.language==='zh-CN' ? zh : en;
  const path = route||window.location.pathname;
  const query = new URLSearchParams(window.location.search);
  const requestedTab = section||path.split('/')[2] || query.get('tab') || 'general';
  const tab = ['general','models','connections','identity','channels'].includes(requestedTab) ? requestedTab : 'general';
  const detailId = path.match(/\/settings\/connections\/([^/]+)\/?$/)?.[1];
  useEffect(()=>{if(!section&&!route&&!detailId && path!=='/settings/'+tab){history.replaceState(null,'','/settings/'+tab);window.dispatchEvent(new PopStateEvent('popstate'));}},[path,tab,detailId]);
  useEffect(()=>{document.querySelector('.settings-tabs a[aria-current=page]')?.scrollIntoView({block:'nearest',inline:'nearest'});},[tab]);
  if(detailId&&(decodeURIComponent(detailId)==='wechat-sync-local'||matchesProvider(ctx.state.connections.find(c=>c.id===decodeURIComponent(detailId))||{provider:decodeURIComponent(detailId)} as Connection,'wechat')))return <WechatConnection ctx={ctx} t={t}/>;
  return detailId ? <Customize key={detailId} ctx={ctx} id={decodeURIComponent(detailId)} t={t}/> : <main className="settings-page" data-page={'settings-'+tab}>
    <header className="settings-header"><h1>{t('Settings','设置')}</h1><nav className="settings-tabs" aria-label={t('Settings sections','设置分区')}>{[['general','General','通用'],['models','Models','模型'],['connections','Connections','连接'],['identity','Identity','身份'],['channels','Channels','渠道']].map(([key,en,zh])=><a key={key} href={'/settings/'+key} aria-current={tab===key?'page':undefined} onClick={e=>{e.preventDefault();ctx.navigate('/settings/'+key);}}>{t(en,zh)}</a>)}</nav><div className="settings-subheader"><p>{tab==='models'?t('Choose the models your twin uses.','选择分身实际使用的模型。'):tab==='general'?t('Basic preferences for how OpsTwins looks.','设置 OpsTwins 的界面显示方式。'):tab==='identity'?t('Who your twin is, and what it remembers. Both are saved records you can read, edit, and roll back.','分身是谁，以及它记住了什么。二者都是可读取、编辑和恢复的已保存记录。'):tab==='channels'?t('Create a chat channel to talk to your twin in Feishu.','创建飞书聊天渠道，在飞书中与分身对话。'):t('Choose which apps your twin can use, and what it may do in each one.','选择分身可使用的应用，以及在各应用中的权限。')}</p><span className="settings-summary">{tab==='models'?t('Standard · Deep thinking','普通任务 · 深度思考'):tab==='general'?t('Interface: English','界面：简体中文'):tab==='channels'?t('Chat channels','聊天渠道'):tab==='identity'?t(`Revision ${ctx.state.revision}`,`版本 ${ctx.state.revision}`):t(`${ctx.state.connections.filter(c=>!unsupported(c.provider||'')&&c.status==='connected').length} connected, including ${ctx.state.connections.filter(c=>!unsupported(c.provider||'')&&!c.supersededBy&&!providers.some(p=>matchesProvider(c,p.id))&&c.status==='connected').length} custom app${ctx.state.connections.filter(c=>!unsupported(c.provider||'')&&!c.supersededBy&&!providers.some(p=>matchesProvider(c,p.id))&&c.status==='connected').length===1?'':'s'}`,`${ctx.state.connections.filter(c=>!unsupported(c.provider||'')&&c.status==='connected').length} 个已连接，其中 ${ctx.state.connections.filter(c=>!unsupported(c.provider||'')&&!c.supersededBy&&!providers.some(p=>matchesProvider(c,p.id))&&c.status==='connected').length} 个自定义应用`)}</span></div></header>
    {tab==='models'?<ModelSettings t={t}/>:tab==='general'?<General ctx={ctx} t={t}/>:tab==='identity'?<Identity ctx={ctx} t={t}/>:tab==='channels'?<Channels ctx={ctx} t={t}/>:<Connections ctx={ctx} t={t}/>}
  </main>;
}

function General({ctx,t}:{ctx:UIContext;t:Translate}) {
  const saved=ctx.state.settings.identity.language;
  const validSaved=['en','zh-CN'].includes(saved);
  const [language,setLanguage]=useState(()=>{try{const draft=sessionStorage.getItem('opsadv-settings-general-draft');if(draft==='en'||draft==='zh-CN')return draft;}catch{}return validSaved?saved:'en';});
  const [busy,setBusy]=useState(false),[error,setError]=useState(''),[success,setSuccess]=useState(false),[external,setExternal]=useState(false);
  const dirty=language!==saved;
  const priorSaved=useRef(saved);
  const formRef=useRef<HTMLFormElement>(null);
  useEffect(()=>{if(priorSaved.current!==saved){if(language===priorSaved.current)setLanguage(validSaved?saved:'en');else if(language!==saved)setExternal(true);priorSaved.current=saved;}},[saved,language,validSaved]);
  useEffect(()=>{try{if(dirty)sessionStorage.setItem('opsadv-settings-general-draft',language);else sessionStorage.removeItem('opsadv-settings-general-draft');}catch{}},[language,dirty]);
  async function save(e:React.FormEvent) {
    e.preventDefault();if(busy||!dirty)return;setBusy(true);setError('');setSuccess(false);
    try{const settings=await api.patch<SettingsData>('/settings',{identity:{language}});if(settings.identity.language!==language)throw new Error(t('Saved value could not be confirmed. Refresh and check again.','无法确认保存结果，请刷新后再次核对。'));ctx.applySettings(settings);setExternal(false);setSuccess(true);requestAnimationFrame(()=>formRef.current?.querySelector<HTMLInputElement>('input:checked')?.focus());}
    catch(e){setError((e as Error).message);}finally{setBusy(false);}
  }
  return <form ref={formRef} className="settings-general" onSubmit={save} aria-busy={busy}>
    <section className="settings-panel settings-card settings-language-card" aria-labelledby="language-title">
      <div className="settings-panel-title settings-language-heading"><h2 id="language-title">{t('Language','语言')}</h2><p id="language-note" className="settings-language-description">{t('Used for menus and pages. Tell your twin which language to use in chat.','用于菜单和页面。沟通语言可以直接在聊天中告诉分身。')}</p></div>
      <fieldset className="settings-language-options" disabled={busy} aria-describedby="language-note" onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();formRef.current?.requestSubmit();}}}><legend className="sr-only">{t('Interface language','界面语言')}</legend>
        {[['en','English','English'],['zh-CN','简体中文','Simplified Chinese']].map(([value,native,description])=>{const secondary=value==='en'?t('English','英文'):t(description,'简体中文');return <label key={value} className={'settings-language-option'+(language===value?' selected':'')}><span className={'settings-language-glyph '+value} aria-hidden="true">{value==='en'?'Aa':'文'}</span><span className="settings-language-label"><strong lang={value}>{native}</strong>{secondary!==native&&<small id={'language-desc-'+value}>{secondary}</small>}</span>{saved===value&&<span className="settings-tag settings-status-on">{t('Current','当前')}</span>}<input type="radio" name="language" value={value} checked={language===value} aria-label={native} aria-describedby={secondary!==native?'language-desc-'+value:undefined} onChange={()=>{setLanguage(value);setError('');setSuccess(false);}}/></label>;})}
      </fieldset>
      {!validSaved&&<p className="settings-hint">{t('Choose a language and save to fix this setting.','请选择语言并保存以修复此设置。')}</p>}
      {external&&<p className="settings-hint" role="status">{t('Language was changed elsewhere. Your choice is kept; save or cancel.','语言已在其他地方变更。你的选择已保留，请保存或取消。')}</p>}
      {error&&<div className="settings-error" role="alert">{t('Couldn’t save language:','无法保存语言：')} {error}</div>}
      {success&&<div className="settings-result" role="status">{t('Language saved. OpsTwins is now in English.','语言已保存，OpsTwins 已切换为简体中文。')}</div>}
      <div className="settings-language-footer"><span className={dirty?'settings-tag settings-status-wait':'settings-hint'} role="status">{busy?t('Saving…','保存中…'):dirty?t('Unsaved change','尚未保存'):t('Changes apply to the whole app after you save.','保存后在整个应用中生效。')}</span><div className="settings-language-actions"><button type="button" className="settings-button" disabled={busy||!dirty} onClick={()=>{setLanguage(validSaved?saved:'en');setError('');setExternal(false);setSuccess(false);}}>{t('Cancel','取消')}</button><button type="submit" className="settings-button settings-button-primary" disabled={busy||!dirty}>{busy?t('Saving…','保存中…'):t('Save','保存')}</button></div></div>
    </section>
  </form>;
}

function Connections({ctx,t}:{ctx:UIContext;t:Translate}) {
  const [cached]=useState(()=>desktopConnectionDraft('new'));const [type,setType]=useState(cached?.type||'mcp');const [name,setName]=useState(cached?.name||'');const [endpoint,setEndpoint]=useState(cached?.endpoint||'');
  const [auth,setAuth]=useState(cached?.auth||'none');const [apiKey,setApiKey]=useState('');const [permissions,setPermissions]=useState<string[]>(cached?.permissions||['read','draft','send']);
  const [busy,setBusy]=useState('');const [error,setError]=useState('');const [result,setResult]=useState('');const [modal,setModal]=useState<ModalState>(null);
  const [requestName,setRequestName]=useState('');const [requestReason,setRequestReason]=useState('');const [requested,setRequested]=useState<Entity|null>(null);
  useEffect(()=>{try{saveDesktopConnectionDraft('new',{type,name,endpoint,auth,permissions})}catch(e:any){setError(e.message)}},[type,name,endpoint,auth,permissions]);
  const custom=ctx.state.connections.filter(c=>!unsupported(c.provider||'')&&!c.supersededBy&&!providers.some(p=>matchesProvider(c,p.id)));
  async function test(provider?:Provider) {
    setError('');setResult('');setBusy(provider?.id || 'custom');
    try {
      if(!provider && (!name.trim() || !endpoint.trim())) throw new Error(t('Enter an app name and server URL or skill path.','请填写应用名称与服务器地址或 Skill 路径。'));
      if(!provider && auth==='api-key' && !apiKey.trim()) throw new Error(t('Enter an API key, or choose No sign-in.','请填写 API key，或选择无需认证。'));
      if(!provider){saveDesktopConnectionDraft('new',{type,name,endpoint,auth,permissions});await window.OpsTwinsDesktop?.durable()}const existing=provider?connectionFor(ctx,provider.id):undefined;
      const response=await testConnectionRequest(ctx,provider?.id||'custom',provider?{type:existing?.type||'provider',provider:provider.id,name:provider.name,permissions:existing?.permissions||['read','draft','send']}:{type,provider:'custom',name:name.trim(),endpoint:endpoint.trim(),permissions,config:{authMethod:auth,...(apiKey?{apiKey}:{})}},existing);
      setApiKey('');await ctx.refresh();
      if(!response.ok){setError(response.message || t('Connection could not be verified. Open Customize to finish setup.','无法验证连接。请打开自定义页面完成配置。'));if(provider&&response.connection?.id)setModal({kind:'provider-setup',id:response.connection.id,provider:provider.id});}
      else{setResult(response.message || t('Connection verified and saved.','连接已验证并保存。'));if(!provider){setName('');setEndpoint('');}}
    }catch(e){setError(failMessage(e));}finally{setBusy('');}
  }
  async function requestApp(e:React.FormEvent) {
    e.preventDefault();setBusy('request');setError('');
    try{const value=await api.post<any>('/tasks',{title:`Request app: ${requestName.trim()}`,notes:requestReason.trim(),status:'pending',source:'settings-app-request',category:'integration'});setRequested(itemResult<Entity>(value,'task'));await ctx.refresh();setRequestName('');setRequestReason('');}catch(e){setError(failMessage(e));}finally{setBusy('');}
  }
  return <>
    {error&&<div className="settings-error" role="alert">{error}</div>}{result&&<div className="settings-result" role="status">{result}</div>}
    <div className="settings-grid">{providers.filter(p=>!unsupported(p.id)).map(p=>{
      const c=connectionFor(ctx,p.id);const unavailable=unsupported(p.id);const connected=!unavailable&&c?.status==='connected';const gmailSetup=p.id==='gmail'&&!connected;
      return <section className="settings-card" key={p.id} data-provider={p.id}>
        <div className="settings-card-head"><ProviderIcon provider={p}/><div className="settings-provider-meta"><span className="settings-provider-name">{t(p.name,p.zh)}</span><span className="settings-provider-caption">{c?.config?.account || c?.config?.workspace || c?.evidence?.name || t(p.caption,p.captionZh)}</span></div><Status status={unavailable?'unsupported':c?.status||'not_connected'} t={t}/></div>
        {unavailable?<p className="settings-provider-description">{t('This integration is not available yet.','当前版本暂不支持此应用接入。')}</p>:gmailSetup?<p className="settings-provider-description">{t('Connect through an authorized email adapter. Direct Google sign-in is not available yet.','通过已授权的邮件适配器接入。Google 账号一键授权尚未开放。')}</p>:connected?<div className="settings-permission-list">{p.features.map((feature,i)=><span key={feature}><span style={{color:'#1E6B32'}}><Icon kind="check" size={16}/></span>{t(feature,p.featuresZh[i])}</span>)}</div>:<span className="settings-provider-description">{t(p.description,p.descriptionZh)}</span>}
        <div className="settings-card-actions">{unavailable?<span className="settings-hint">{t('Connection unavailable','暂无法连接')}</span>:p.id==='wechat'?<button className="settings-button settings-button-primary" onClick={()=>ctx.navigate('/settings/connections/wechat-sync-local')}>{connected?t('Browse WeChat','查看微信'):t('Connect WeChat','连接个人微信')}</button>:gmailSetup?<button className="settings-button settings-button-primary" onClick={()=>setModal({kind:'gmail-setup',id:c?.id})}>{t('Set up Gmail','设置 Gmail 连接')}</button>:<>
          {connected||c?<a className="settings-button" href={'/settings/connections/'+enc(c?.id||p.id)} onClick={e=>{e.preventDefault();ctx.navigate('/settings/connections/'+enc(c?.id||p.id));}}>{t('Customize','自定义')}</a>:<button className="settings-button settings-button-primary" onClick={()=>test(p)} disabled={!!busy}>{busy===p.id?t('Testing…','检测中…'):t('Connect','连接')}</button>}
          {connected&&<span className="settings-last-sync">{relativeSync(c?.config?.lastSyncedAt||c?.config?.lastTestedAt||c?.lastSyncedAt||c?.lastTestAt||c?.updatedAt,t)}</span>}
          {!connected&&c&&<button className="settings-button settings-button-small settings-button-primary" onClick={()=>test(p)} disabled={!!busy}>{busy===p.id?t('Testing…','检测中…'):t('Reconnect','重新连接')}</button>}
        </>}</div>
      </section>;
    })}</div>
    <section className="settings-card settings-custom-card"><div className="settings-card-head"><span className="settings-provider-icon" style={{background:'transparent',border:'1.5px dashed #AEAEB2',color:'#424245'}}><Icon kind="plus" size={20}/></span><div className="settings-provider-meta"><span className="settings-provider-name">{t('Add a custom app','添加自定义应用')}</span><span className="settings-provider-caption">{t('Connect any tool your team uses, such as a CRM, help desk or internal system.','连接团队使用的工具，例如 CRM、服务台或内部系统。')}</span></div></div>
      <form onSubmit={e=>{e.preventDefault();test();}} className="settings-custom-form"><div className="settings-field"><span>{t('Connect with','连接方式')}</span><div className="settings-segment" role="group" aria-label={t('Connection type','连接类型')}>{[['mcp','MCP server','MCP 服务器'],['rest','REST API','REST API'],['webhook','Webhook','Webhook'],['skill','Skill','Skill']].map(([key,en,zh])=><button key={key} type="button" aria-pressed={type===key} onClick={()=>{setType(key);setError('');}} disabled={!!busy}>{t(en,zh)}</button>)}</div></div><label className="settings-field settings-field-grow">{t('Name','名称')}<input required className="settings-input" value={name} onChange={e=>setName(e.target.value)} placeholder={t('For example, Zendesk','例如 Zendesk')} disabled={!!busy}/></label><label className="settings-field settings-field-url">{type==='skill'?t('Skill path','Skill 路径'):t('Server URL','服务器 URL')}<input required className="settings-input" value={endpoint} onChange={e=>setEndpoint(e.target.value)} placeholder={type==='skill'?'/path/to/SKILL.md':'https://'} disabled={!!busy}/></label><label className="settings-field">{t('Sign-in','认证')}<select className="settings-select" value={auth} onChange={e=>setAuth(e.target.value)} disabled={!!busy}><option value="oauth">OAuth</option><option value="api-key">API key</option><option value="none">{t('No sign-in','无需认证')}</option></select></label><button className="settings-button settings-button-primary" type="submit" disabled={!!busy}>{busy==='custom'?t('Testing…','检测中…'):t('Test and connect','检测并连接')}</button></form>
      {auth==='api-key'&&<label className="settings-field">{t('API key (stored privately by the server)','API key（仅服务端私密保存）')}<input className="settings-input" type="password" autoComplete="off" value={apiKey} onChange={e=>setApiKey(e.target.value)} placeholder={t('Enter API key','输入 API key')} disabled={!!busy}/></label>}
      <div className="settings-custom-permissions"><span className="settings-hint">{t('Your twin may:','分身可以：')}</span>{[['read','Read','读取'],['draft','Draft','草稿'],['send','Send with your approval','审批后发送'],['auto','Send automatically','自动发送']].map(([key,en,zh])=><label className="settings-checkbox" key={key}><input type="checkbox" checked={permissions.includes(key)} onChange={e=>setPermissions(prev=>e.target.checked?Array.from(new Set([...prev,...(key!=='read'?['read']:[]),...(key==='auto'?['send']:[]),key])):prev.filter(p=>p!==key&&!(key==='read'&&['draft','send','auto'].includes(p))&&!(key==='send'&&p==='auto')))} disabled={!!busy}/>{t(en,zh)}</label>)}</div>
      <div className="settings-custom-list"><span className="settings-custom-list-title">{t('Your custom apps','你的自定义应用')}</span>{custom.length?custom.map(c=><div className="settings-custom-row" key={c.id}><ProviderIcon provider={{letter:(c.name||'A').slice(0,1).toUpperCase(),bg:'#FFF1DC',color:'#8A4B00'}}/><div className="settings-custom-row-main"><div className="settings-inline-tags"><span className="settings-custom-name">{c.name}</span><span className="settings-tag settings-tag-purple">{c.type==='mcp'?'MCP server':c.type==='rest'?'REST API':c.type}</span><Status status={c.status} t={t}/></div><span className="settings-mono settings-endpoint">{c.endpoint} · {c.config?.authMethod || t('No sign-in','无需认证')}{c.config?.toolCount!==undefined?` · ${c.config.toolCount} tools`:c.type==='mcp'?` · ${(c.capabilities||[]).length} tools`:''}</span><span className="settings-provider-description">{c.config?.description || c.config?.lastTestMessage || c.message || ''}</span></div><div className="settings-custom-row-actions"><div className="settings-inline-tags">{(c.permissions||[]).slice(0,4).map(p=><span key={p} className="settings-tag settings-custom-permission-tag">{p}</span>)}</div><a className="settings-button settings-button-small" href={'/settings/connections/'+enc(c.id)} onClick={e=>{e.preventDefault();ctx.navigate('/settings/connections/'+enc(c.id));}}>{t('Customize','自定义')}</a></div></div>):<div className="settings-empty">{t('Add your first app above. A connection appears here after its actual test.','在上方添加首个应用。完成实际检测后，连接会显示在此处。')}</div>}</div>
    </section>
    <div className="settings-trust-banner"><span className="settings-trust-icon"><Icon kind="shield"/></span><span>{t('Your twin only uses your own permissions in each app. Disconnect any app at any time, and every action is recorded in Activity.','分身仅使用你在各应用中的权限。可以随时断开应用，每次操作都会记录在 Activity 中。')}</span><button className="settings-button" onClick={()=>{setModal({kind:'request'});setRequested(null);setError('');}}>{t('Request another app','申请其他应用')}</button></div>
    {modal?.kind==='request'&&<Modal title={t('Request another app','申请其他应用')} onClose={()=>setModal(null)} busy={!!busy}>{requested?<><div className="settings-result" role="status">{t('Your integration request is saved as a task.','应用接入申请已保存为任务。')}</div><p>{requested.title}</p><p className="settings-mono">{requested.id}</p><div className="settings-modal-actions"><button className="settings-button settings-button-primary" onClick={()=>setModal(null)}>{t('Done','完成')}</button></div></>:<form onSubmit={requestApp} style={{display:'flex',flexDirection:'column',gap:16}}><p>{t('Tell your twin which app you need and why. The request stays in your tasks until it is resolved.','告诉分身需要哪个应用以及用途。申请将保留在任务中直到处理完成。')}</p><label className="settings-field">{t('App name','应用名称')}<input className="settings-input" required value={requestName} onChange={e=>setRequestName(e.target.value)} disabled={!!busy}/></label><label className="settings-field">{t('What do you want to do with it?','希望用它完成什么？')}<textarea className="settings-textarea" required value={requestReason} onChange={e=>setRequestReason(e.target.value)} disabled={!!busy}/></label>{error&&<div className="settings-error" role="alert">{error}</div>}<div className="settings-modal-actions"><button type="button" className="settings-button" onClick={()=>setModal(null)} disabled={!!busy}>{t('Cancel','取消')}</button><button type="submit" className="settings-button settings-button-primary" disabled={!!busy}>{busy?t('Saving…','保存中…'):t('Save request','保存申请')}</button></div></form>}</Modal>}
    {modal?.kind==='gmail-setup'&&<Modal title={t('Connect Gmail','连接 Gmail')} onClose={()=>setModal(null)}>
      <p>{t('Direct Google sign-in is not available in this version. No Google account has been authorized by opening this dialog.','此版本尚未提供 Google 一键登录。打开此窗口不会授权或连接你的 Google 账号。')}</p>
      <ol className="settings-gmail-steps"><li>{t('Use a Gmail adapter that has already completed Google authorization.','准备已完成 Google 授权的 Gmail 适配器。')}</li><li>{t('Configure its MCP or REST endpoint and verify the connection.','配置适配器的 MCP 或 REST 服务地址，并检测连接。')}</li><li>{t('A successful endpoint test verifies the adapter only; mailbox sync and sending require separate support.','端点检测成功仅代表适配器可用；邮箱同步与发送能力需单独接入。')}</li></ol>
      <div className="settings-modal-actions"><button className="settings-button" onClick={()=>setModal(null)}>{t('Cancel','取消')}</button><button className="settings-button settings-button-primary" onClick={()=>{setModal(null);setType('mcp');setName('Gmail adapter');setEndpoint('');setAuth('none');setApiKey('');requestAnimationFrame(()=>{const field=document.querySelector<HTMLInputElement>('.settings-custom-card input');field?.scrollIntoView({block:'center'});field?.focus();});}}>{t('Configure adapter','配置邮件适配器')}</button></div>
    </Modal>}
    {modal?.kind==='provider-setup'&&<Modal title={t('Finish connection setup','完成连接配置')} onClose={()=>setModal(null)}><p>{error}</p><div className="settings-modal-actions"><button className="settings-button" onClick={()=>setModal(null)}>{t('Close','关闭')}</button><button className="settings-button settings-button-primary" onClick={()=>ctx.navigate('/settings/connections/'+enc(modal.id!))}>{t('Open Customize','打开自定义')}</button></div></Modal>}
  </>;
}

function Identity({ctx,t}:{ctx:UIContext;t:Translate}) {
  const identity=ctx.state.settings.identity;
  const [profile,setProfile]=useState({...identity});const [editing,setEditing]=useState(false);const [memoryEditing,setMemoryEditing]=useState(false);
  const [memoryDraft,setMemoryDraft]=useState<MemoryDraft[]>([]);const fullMemoryRef=useRef<Entity[]>([]);const [busy,setBusy]=useState('');const [error,setError]=useState('');const [history,setHistory]=useState<any[]|null>(null);const [historyKind,setHistoryKind]=useState('identity');
  const activeMemories=ctx.state.memories.filter(m=>!m.deletedAt && !m.deleted);
  useEffect(()=>{if(!editing)setProfile({...identity});},[identity,editing]);
  const soul=`# Soul\n\n## Who I am\nI'm the work twin of ${identity.name || 'Steve'}.\n${identity.role?`${identity.role}\n`:''}${identity.about?`${identity.about}\n`:''}\n## How I work\n${identity.instructions || 'Ask before sending messages or making commitments.'}`;
  const groups = new Map<string,Entity[]>();activeMemories.forEach(m=>{const cat=m.category||'Learned';groups.set(cat,[...(groups.get(cat)||[]),m]);});
  const memoryText='# Memory\n'+Array.from(groups).map(([category,items])=>'\n## '+category+'\n'+items.map(m=>'- '+(m.content||m.body||m.description||m.title||'')).join('\n')).join('\n');
  async function saveProfile(e:React.FormEvent) {
    e.preventDefault();setBusy('identity');setError('');
    try{const {language: _language,...identityPatch}=profile;await api.patch('/settings',{identity:identityPatch});await ctx.refresh();setEditing(false);ctx.notify(t('Identity saved','身份已保存'),'success');}catch(e){setError(failMessage(e));}finally{setBusy('');}
  }
  async function editMemories(){setBusy('memory-load');setError('');try{const full=await Promise.all(activeMemories.map(async m=>itemResult<Entity>(await api.get('/memories/'+enc(m.id)),'memory')));fullMemoryRef.current=full;setMemoryDraft(full.map(m=>({...m,content:m.content||m.body||m.description||m.title||'',category:m.category||'Learned'})));setMemoryEditing(true);}catch(e){setError(failMessage(e));}finally{setBusy('');}}
  async function saveMemories() {
    setBusy('memory');setError('');
    try {
      if(memoryDraft.some(m=>!m.removed&&!m.content.trim())) throw new Error(t('A memory cannot be empty. Remove it or add text.','记忆不能留空。请删除该条或填写内容。'));
      await api.post('/memories/snapshot',{});
      for(const m of memoryDraft){if(m.removed){if(!m.isNew)await api.delete('/memories/'+enc(m.id));continue;}const original=fullMemoryRef.current.find(a=>a.id===m.id);const data={title:m.content.split('\n')[0].slice(0,100),content:m.content.trim(),body:m.content.trim(),category:m.category.trim()||'Learned'};if(m.isNew){const created=itemResult<Entity>(await api.post('/memories',data),'memory');fullMemoryRef.current.push(created);setMemoryDraft(prev=>prev.map(a=>a.id===m.id?{...created,content:data.content,category:data.category,isNew:false}:a));}else if(m.content!==(original?.content||original?.body||original?.description||original?.title)||m.category!==(original?.category||'Learned')){const changed=itemResult<Entity>(await api.patch('/memories/'+enc(m.id),data),'memory');fullMemoryRef.current=fullMemoryRef.current.map(a=>a.id===m.id?changed:a);}}
      await ctx.refresh();setMemoryEditing(false);ctx.notify(t('Memory saved','记忆已保存'),'success');
    }catch(e){setError(failMessage(e));await ctx.refresh().catch(()=>{});}finally{setBusy('');}
  }
  async function openHistory(kind:string){setHistoryKind(kind);setError('');setBusy('history');try{if(kind==='memory')setHistory(listResult<any>(await api.get('/memories/history'),'history'));else setHistory(listResult<any>(await api.get('/settings/history'),'history'));}catch(e){setError(failMessage(e));}finally{setBusy('');}}
  function historyIdentity(row:any){const raw=row.settings||row.snapshot||row.value||row.before||row.data;return raw?.identity||row.identity;}
  async function restore(row:any) {
    setBusy('restore');setError('');
    try {
      if(historyKind==='identity'){const previous=historyIdentity(row);if(!previous)throw new Error(t('This revision has no identity data to restore.','该版本不包含可恢复的身份资料。'));await api.patch('/settings',{identity:previous});setEditing(false);}
      else {
        await api.post('/memories/history/'+enc(row.id)+'/restore',{});
        setMemoryEditing(false);
      }
      await ctx.refresh();setHistory(null);ctx.notify(t('Revision restored','版本已恢复'),'success');
    }catch(e){setError(failMessage(e));await ctx.refresh().catch(()=>{});}finally{setBusy('');}
  }
  return <>{error&&<div className="settings-error" role="alert">{error}</div>}<div className="settings-identity-grid">
    <section className="settings-document" data-document="soul"><div className="settings-document-header"><span className="settings-document-icon"><Icon kind="file"/></span><div className="settings-document-meta"><span className="settings-document-name settings-mono">soul.md</span><span className="settings-document-caption">{t('Personality, voice and rules. Written by you.','个性、表达与规则，由你撰写。')}</span></div><button className="settings-button settings-button-small" onClick={()=>openHistory('identity')} disabled={!!busy}>{t('History','历史')}</button>{!editing&&<button className="settings-button settings-button-small settings-button-primary" onClick={()=>{setProfile({...identity});setEditing(true);setError('');}}>{t('Edit','编辑')}</button>}</div>
      {editing?<form className="settings-editor" onSubmit={saveProfile}><div className="settings-profile-fields"><label className="settings-field">{t('Your name','姓名')}<input className="settings-input" value={profile.name} required onChange={e=>setProfile({...profile,name:e.target.value})} disabled={!!busy}/></label><label className="settings-field">{t('Role','角色')}<input className="settings-input" value={profile.role} onChange={e=>setProfile({...profile,role:e.target.value})} disabled={!!busy}/></label><label className="settings-field settings-field-wide">{t('About you','关于你')}<input className="settings-input" value={profile.about} onChange={e=>setProfile({...profile,about:e.target.value})} disabled={!!busy}/></label></div><label className="settings-field" style={{flex:1}}>{t('Instructions (Markdown)','指令（Markdown）')}<textarea className="settings-textarea" value={profile.instructions} onChange={e=>setProfile({...profile,instructions:e.target.value})} disabled={!!busy}/></label><div className="settings-modal-actions"><button type="button" className="settings-button" onClick={()=>{setEditing(false);setProfile({...identity});setError('');}} disabled={!!busy}>{t('Cancel','取消')}</button><button type="submit" className="settings-button settings-button-primary" disabled={!!busy}>{busy==='identity'?t('Saving…','保存中…'):t('Save','保存')}</button></div></form>:<div className="settings-document-content"><Markdown text={soul}/></div>}
      <div className="settings-document-footer">{t('Your saved identity is used for new drafts and conversations.','保存的身份资料用于新的草稿和对话。')} <a href="/settings/general" onClick={e=>{e.preventDefault();ctx.navigate('/settings/general');}} style={{color:'#0071E3'}}>{t('Interface language is in General ›','界面语言在“通用”中设置 ›')}</a></div>
    </section>
    <section className="settings-document" data-document="memory"><div className="settings-document-header"><span className="settings-document-icon settings-document-icon-blue"><Icon kind="file"/></span><div className="settings-document-meta"><span className="settings-document-name settings-mono">memory.md</span><span className="settings-document-caption">{t('Saved knowledge and communication preferences. Tell your twin a preference, or edit it here.','保存的知识与沟通偏好。可以在聊天中设置偏好，也可以在此编辑或删除。')}</span></div><button className="settings-button settings-button-small" onClick={()=>openHistory('memory')} disabled={!!busy}>{t('History','历史')}</button>{!memoryEditing&&<button className="settings-button settings-button-small settings-button-primary" onClick={editMemories}>{t('Edit','编辑')}</button>}</div>
      {memoryEditing?<div className="settings-editor">{memoryDraft.filter(m=>!m.removed).map(m=><div className="settings-memory-editor" key={m.id}><div className="settings-memory-head"><input aria-label={t('Memory category','记忆分类')} className="settings-input" value={m.category} onChange={e=>setMemoryDraft(prev=>prev.map(a=>a.id===m.id?{...a,category:e.target.value}:a))} disabled={!!busy}/><button className="settings-memory-delete" onClick={()=>setMemoryDraft(prev=>prev.map(a=>a.id===m.id?{...a,removed:true}:a))} disabled={!!busy}>{t('Delete','删除')}</button></div><textarea aria-label={t('Memory text','记忆内容')} className="settings-textarea" value={m.content} onChange={e=>setMemoryDraft(prev=>prev.map(a=>a.id===m.id?{...a,content:e.target.value}:a))} disabled={!!busy}/></div>)}<button className="settings-button settings-button-dashed" style={{alignSelf:'flex-start'}} onClick={()=>setMemoryDraft(prev=>[...prev,{id:'new-'+crypto.randomUUID(),content:'',category:'Learned',isNew:true}])} disabled={!!busy}>{t('+ Add memory','+ 添加记忆')}</button><div className="settings-modal-actions"><button className="settings-button" onClick={()=>{setMemoryEditing(false);setError('');}} disabled={!!busy}>{t('Cancel','取消')}</button><button className="settings-button settings-button-primary" onClick={saveMemories} disabled={!!busy}>{busy==='memory'?t('Saving…','保存中…'):t('Save','保存')}</button></div></div>:<div className="settings-document-content"><Markdown text={memoryText}/>{!activeMemories.length&&<div style={{color:'#6E6E73'}}>{t('\nNo saved memories yet. Use Edit to add a fact.','\n还没有保存的记忆。点击编辑添加知识。')}</div>}</div>}
      <div className="settings-document-footer">{t(`${activeMemories.length} saved facts · Preview summaries; Edit loads original text`,`${activeMemories.length} 条已保存记忆 · 此处显示摘要，编辑会读取完整原文`)}</div>
    </section>
  </div>{history!==null&&<Modal title={historyKind==='memory'?t('Memory history','记忆历史'):t('Identity history','身份历史')} onClose={()=>setHistory(null)} busy={!!busy}><p>{historyKind==='memory'?t('Restore a saved memory snapshot. Your current memories are saved before restoring.','恢复记忆快照前，会先保存当前记忆。'):t('Restore your profile and instructions. Connections and Autonomy stay as they are.','恢复本人资料与指令。连接和自主规则会保持当前设置。')}</p>{error&&<div className="settings-error" role="alert">{error}</div>}<div className="settings-history-list">{history.length?history.map((row,i)=><div className="settings-history-item" key={row.id||i}><div><span className="settings-hint">{new Date(row.createdAt||row.timestamp||Date.now()).toLocaleString()}</span><button className="settings-button settings-button-small" onClick={()=>restore(row)} disabled={!!busy||(historyKind==='identity'&&!historyIdentity(row))}>{t('Restore','恢复')}</button></div><pre>{historyKind==='memory'?(row.preview||t(`${row.count ?? row.memoryCount ?? 0} saved memories`,`${row.count ?? row.memoryCount ?? 0} 条记忆`)):historyIdentity(row)?.instructions || t('No identity data in this revision','该版本没有身份资料')}</pre></div>):<div className="settings-empty">{t('No previous revisions yet. A revision is saved when you make a change.','尚无历史版本。修改时会保留版本。')}</div>}</div></Modal>}</>;
}

function Channels({t}:{ctx:UIContext;t:Translate}) {
  return <FeishuBinding t={t}/>;
}

function Customize({ctx,id,t}:{ctx:UIContext;id:string;t:Translate}) {
  const selected=ctx.state.connections.find(c=>c.id===id)||connectionFor(ctx,id);
  const found=selected&&matchesProvider(selected,'feishu')?connectionFor(ctx,'feishu'):selected;
  const provider=providers.find(p=>matchesProvider(found||{id,provider:id,name:id,type:'provider',status:'setup_required'},p.id));
  const connection:Connection=found||{id,name:provider?.name||id,provider:provider?.id||id,type:'provider',status:'setup_required',permissions:['read'],config:{}};
  const [cached]=useState(()=>desktopConnectionDraft(connection.id));const lease=useRef(cached?.baseline||connection.updatedAt),saveQueue=useRef(Promise.resolve(false));const [config,setConfig]=useState<any>(cached?{...connection.config,...cached.config}:connection.config||{});const [permissions,setPermissions]=useState<string[]>(cached?.permissions||connection.permissions||['read']);const [endpoint,setEndpoint]=useState(cached?.endpoint??connection.endpoint??'');
  const [busy,setBusy]=useState('');const [error,setError]=useState('');const [result,setResult]=useState('');const [dirty,setDirty]=useState(!!cached);const [modal,setModal]=useState<string|null>(null);const [text,setText]=useState('');const [role,setRole]=useState('VIP');const [scopeMode,setScopeMode]=useState('draft');const [secret,setSecret]=useState('');
  useEffect(()=>{if(dirty){if(!busy&&lease.current!==connection.updatedAt)setError(t('This connection changed elsewhere. Your edits are kept; review before saving.','此连接已在其他地方变更。当前编辑已保留，请核对后再保存。'));return;}lease.current=connection.updatedAt;setConfig(connection.config||{});setPermissions(connection.permissions||['read']);setEndpoint(connection.endpoint||'');},[connection.id,connection.updatedAt]);
  const draftRef=useRef({config,permissions,endpoint});draftRef.current={config,permissions,endpoint};
  useEffect(()=>{if(dirty)try{saveDesktopConnectionDraft(connection.id,{config,permissions,endpoint,baseline:lease.current})}catch(e:any){setError(e.message)}},[config,permissions,endpoint,dirty]);
  const icon=provider||{letter:(connection.name||'A').slice(0,1).toUpperCase(),bg:'#FFF1DC',color:'#8A4B00'};
  const scopes:Scope[]=config.scopes||(matchesProvider(connection,'feishu')?[{id:'all',name:t('All conversations','全部会话'),enabled:true,mode:'draft'}]:[{id:'dm',name:t('Direct messages','私信'),enabled:false,mode:'draft'}]);
  const importantPeople:any[]=config.importantPeople||[];const urgentWords:string[]=config.urgentWords||[];
  function persist(nextConfig=config,nextPermissions=permissions,nextEndpoint=endpoint):Promise<boolean>{
    if(!window.OpsTwinsDesktop)return persistNow(nextConfig,nextPermissions,nextEndpoint);
    const run=saveQueue.current.catch(()=>false).then(()=>persistNow(nextConfig,nextPermissions,nextEndpoint));saveQueue.current=run;return run;
  }
  async function persistNow(nextConfig=config,nextPermissions=permissions,nextEndpoint=endpoint) {
    if(nextConfig.workingHoursOnly&&(nextConfig.workFrom||'08:00')===(nextConfig.workUntil||'19:00')){setError(t('Start and end times must differ. Turn off working-hours restriction for all-day operation.','开始和结束时间不能相同；如需全天使用，请关闭工作时间限制。'));return false;}
    setBusy('save');setError('');setResult('');setDirty(true);
    try{saveDesktopConnectionDraft(connection.id,{config:nextConfig,permissions:nextPermissions,endpoint:nextEndpoint,baseline:lease.current});await window.OpsTwinsDesktop?.durable();let canonical:Connection|undefined;if(found){canonical=await api.patch<Connection>('/connections/'+enc(connection.id),{config:nextConfig,permissions:nextPermissions,endpoint:nextEndpoint,...(window.OpsTwinsDesktop?{baseUpdatedAt:lease.current}:{})});lease.current=canonical.updatedAt;}else {const item=await api.post<any>('/connections',{...(provider?.id==='feishu'?{id:'feishu-local'}:{}),name:connection.name,provider:connection.provider,type:connection.type,status:'setup_required',config:nextConfig,permissions:nextPermissions,endpoint:nextEndpoint});const saved=itemResult<Connection>(item,'connection');await ctx.refresh();ctx.navigate('/settings/connections/'+enc(saved.id));return true;}await ctx.refresh();const unchanged=JSON.stringify(draftRef.current)===JSON.stringify({config:nextConfig,permissions:nextPermissions,endpoint:nextEndpoint});if(!window.OpsTwinsDesktop||unchanged){setDirty(false);saveDesktopConnectionDraft(connection.id,null);if(canonical){setConfig(canonical.config||{});setPermissions(canonical.permissions||[]);setEndpoint(canonical.endpoint||'')}}else{setDirty(true);saveDesktopConnectionDraft(connection.id,{...draftRef.current,baseline:lease.current})}return true;}catch(e){setError(failMessage(e));return false;}finally{setBusy('');}
  }
  function changeConfig(patch:any){const next={...config,...patch};setConfig(next);persist(next);}
  function changePermission(key:string,on:boolean){let next=on?Array.from(new Set([...permissions,...(key==='read'?[]:['read']),...(key==='auto'?['send']:[]),key])):permissions.filter(p=>p!==key&&!(key==='read'&&p!=='read')&&!(key==='send'&&p==='auto'));setPermissions(next);persist(config,next);}
  async function test() {
    setBusy('test');setError('');setResult('');
    try{const body={name:connection.name,provider:connection.provider,type:connection.type,endpoint,permissions,config:{...config,...(secret?{apiKey:secret}:{})}};const response=await testConnectionRequest(ctx,provider?.id||connection.provider,body,found);setSecret('');await ctx.refresh();if(!response.ok)throw new Error(response.message||t('Connection could not be verified.','无法验证连接。'));setResult(response.message||t('Connection verified.','连接已验证。'));if(response.connection?.id&&(!found||response.connection.id!==connection.id))ctx.navigate('/settings/connections/'+enc(response.connection.id));}catch(e){setError(failMessage(e));}finally{setBusy('');}
  }
  async function rebaseDraft(){
    setBusy('read');
    try{const row=await api.get<Connection>('/connections/'+enc(connection.id));lease.current=row.updatedAt;saveDesktopConnectionDraft(connection.id,{...draftRef.current,baseline:lease.current});await window.OpsTwinsDesktop?.durable();await ctx.refresh();setError(t('Latest version loaded. Review your retained draft before saving.','已读取最新版本，草稿保留，请核对后保存。'));}catch(e){setError(failMessage(e));}finally{setBusy('');}
  }
  async function disconnect(){setBusy('disconnect');setError('');try{await api.post('/connections/'+enc(connection.id)+'/disconnect',{});await ctx.refresh();setModal(null);setResult(t('Disconnected. Your saved configuration is kept for reconnecting.','已断开连接，保留配置以便重新连接。'));}catch(e){setError(failMessage(e));}finally{setBusy('');}}
  async function deleteApp(){
    if(!found||provider)return;
    setBusy('delete');setError('');
    try{
      try{await api.delete('/connections/'+enc(connection.id));}catch(e:any){if(e.status!==404)throw e;}
      await ctx.refresh();ctx.navigate('/settings/connections');
    }catch(e){setError(failMessage(e));}finally{setBusy('');}
  }
  function addValue(e:React.FormEvent){e.preventDefault();const value=text.trim();if(!value)return;if(modal==='person')changeConfig({importantPeople:[...importantPeople,{id:crypto.randomUUID(),name:value,role}]});if(modal==='word')changeConfig({urgentWords:Array.from(new Set([...urgentWords,value]))});if(modal==='scope')changeConfig({scopes:[...scopes,{id:crypto.randomUUID(),name:value,mode:scopeMode,enabled:true}]});setText('');setModal(null);}
  const displayName=provider?t(provider.name,provider.zh):connection.name;
  if(!found&&!provider)return <main className="settings-page"><h1>{t('App removed or unavailable','应用已删除或不存在')}</h1><a className="settings-button" href="/settings/connections" onClick={e=>{e.preventDefault();ctx.navigate('/settings/connections');}}>{t('Back to connections','返回连接列表')}</a></main>;

  return <main className="settings-page settings-customize-page" data-page="customize-connection"><a className="settings-back-link" href="/settings/connections" onClick={e=>{e.preventDefault();ctx.navigate('/settings/connections');}}><Icon kind="back"/>{t('Settings · Connections','设置 · 连接')}</a><div className="settings-customize-title"><ProviderIcon provider={icon} large/><div className="settings-provider-meta"><h1>{t(`Customize ${displayName}`,`自定义${displayName}`)}</h1><span className="settings-provider-caption">{connection.status==='connected'?t(`Connected${config.account||config.workspace?' to '+(config.account||config.workspace):''} · ${relativeSync(connection.sync?.completedAt||config.lastSyncedAt||config.lastTestedAt||connection.updatedAt,t).toLowerCase()}`,`已连接${config.account||config.workspace?' '+(config.account||config.workspace):''} · ${relativeSync(connection.sync?.completedAt||config.lastSyncedAt||config.lastTestedAt||connection.updatedAt,t)}`):t('Not connected · configure and test to get started','未连接 · 完成配置并检测后使用')}</span></div><button className={'settings-button'+(connection.status==='connected'?' settings-button-danger':' settings-button-primary')} onClick={()=>connection.status==='connected'?setModal('disconnect'):test()} disabled={!!busy}>{connection.status==='connected'?t('Disconnect','断开连接'):busy==='test'?t('Testing…','检测中…'):t('Reconnect','重新连接')}</button>{found&&!provider&&<button className="settings-button settings-button-danger" onClick={()=>{setError('');setModal('delete');}} disabled={!!busy}>{t('Delete app','删除应用')}</button>}</div>
    {error&&<div className="settings-error" role="alert"><span style={{flex:1}}>{error}</span>{dirty&&<button className="settings-button settings-button-small" onClick={()=>persist()} disabled={!!busy}>{t('Retry save','重试保存')}</button>}{window.OpsTwinsDesktop&&found&&<button className="settings-button settings-button-small" disabled={!!busy} onClick={rebaseDraft}>{t('Read latest, keep draft','读取最新版本，保留草稿')}</button>}</div>}{result&&<div className="settings-result" role="status">{result}</div>}
    <div className="settings-customize-layout"><div className="settings-customize-main">{matchesProvider(connection,'feishu')&&<FeishuSync connected={connection.status==='connected'}/>}<section className="settings-panel"><div className="settings-panel-title"><h2>{t('Channels your twin watches','分身关注的频道')}</h2><span className="settings-hint">{t('Pick what it reads, and how it handles each one.','选择读取范围，以及每个频道的处理方式。')}</span></div>{scopes.map(scope=><div className="settings-panel-row" key={scope.id}><span className="settings-row-title">{scope.name}</span><select className="settings-select" aria-label={t(`Mode for ${scope.name}`,`${scope.name}处理模式`)} value={scope.mode} onChange={e=>changeConfig({scopes:scopes.map(s=>s.id===scope.id?{...s,mode:e.target.value}:s)})} disabled={!!busy}><option value="draft">{t('Draft replies','起草回复')}</option><option value="send_undo">{t('Send with undo','发送且可撤销')}</option><option value="summary">{t('Summarize only','仅摘要')}</option><option value="deep">{t('Deep Think drafts','深度思考草稿')}</option></select><input type="checkbox" role="switch" className="settings-switch" checked={scope.enabled} aria-label={t(`Watch ${scope.name}`,`关注${scope.name}`)} onChange={e=>changeConfig({scopes:scopes.map(s=>s.id===scope.id?{...s,enabled:e.target.checked}:s)})} disabled={!!busy}/>{scope.id!=='dm'&&<button className="settings-memory-delete" aria-label={t(`Remove ${scope.name}`,`删除${scope.name}`)} onClick={()=>changeConfig({scopes:scopes.filter(s=>s.id!==scope.id)})} disabled={!!busy}>×</button>}</div>)}<div className="settings-panel-row"><button className="settings-button settings-button-dashed" onClick={()=>{setText('');setModal('scope');}} disabled={!!busy}>{t('+ Add channel or scope','+ 添加频道或范围')}</button></div></section>
      <section className="settings-card settings-customize-card"><h2>{t(`Important in ${displayName}`,`${displayName}中的重要内容`)}</h2><div className="settings-important-section"><span className="settings-hint">{t('People','人员')}</span><div className="settings-chip-list">{importantPeople.map((person,i)=><span className={'settings-chip'+(person.role==='VIP'?' settings-chip-vip':'')} key={person.id||i}>{person.name} · {person.role}<button aria-label={t(`Remove ${person.name}`,`删除${person.name}`)} onClick={()=>changeConfig({importantPeople:importantPeople.filter((_,j)=>j!==i)})} disabled={!!busy}>×</button></span>)}<button className="settings-button settings-button-dashed" onClick={()=>{setText('');setModal('person');}} disabled={!!busy}>{t('+ Add person','+ 添加人员')}</button></div></div><div className="settings-important-section"><span className="settings-hint">{t('Words that mean urgent','表示紧急的关键词')}</span><div className="settings-chip-list">{urgentWords.map(word=><span className="settings-chip settings-chip-urgent" key={word}>{word}<button aria-label={t(`Remove ${word}`,`删除${word}`)} onClick={()=>changeConfig({urgentWords:urgentWords.filter(w=>w!==word)})} disabled={!!busy}>×</button></span>)}<button className="settings-button settings-button-dashed" onClick={()=>{setText('');setModal('word');}} disabled={!!busy}>{t('+ Add word','+ 添加关键词')}</button></div></div></section>
      <details className="settings-card settings-customize-card settings-sync-details"><summary>{t('Connection and sync rules','连接与同步规则')}<span aria-hidden="true">⌄</span></summary><div className="settings-sync-content"><label className="settings-field">{connection.type==='skill'?t('Skill path','Skill 路径'):t('Server or bridge URL','服务器或桥接 URL')}<input className="settings-input" value={endpoint} onChange={e=>{setEndpoint(e.target.value);setDirty(true);}} placeholder="https://" disabled={!!busy}/></label><div className="settings-compact-grid"><label className="settings-field">{t('Sign-in','认证')}<select className="settings-select" value={config.authMethod||'none'} onChange={e=>changeConfig({authMethod:e.target.value})} disabled={!!busy}><option value="none">{t('No sign-in / local authorization','无需认证 / 本机授权')}</option><option value="oauth">OAuth</option><option value="api-key">API key</option></select></label>{!matchesProvider(connection,'feishu')&&<label className="settings-field">{t('Sync frequency','同步频率')}<select className="settings-select" value={config.syncInterval||'manual'} onChange={e=>changeConfig({syncInterval:e.target.value})} disabled={!!busy}><option value="manual">{t('Manual','手动')}</option><option value="5m">{t('Every 5 minutes','每 5 分钟')}</option><option value="15m">{t('Every 15 minutes','每 15 分钟')}</option><option value="hourly">{t('Every hour','每小时')}</option></select></label>}</div>{config.authMethod==='api-key'&&<label className="settings-field">{t('API key (never shown after saving)','API key（保存后不再显示）')}<input className="settings-input" type="password" autoComplete="off" value={secret} onChange={e=>setSecret(e.target.value)} disabled={!!busy}/></label>}<label className="settings-field">{t('Message filter','消息过滤')}<input className="settings-input" value={config.filter||''} onChange={e=>{setConfig({...config,filter:e.target.value});setDirty(true);}} placeholder={t('Contains this text in sender, message or topic','发件人、消息或主题包含此文字')} disabled={!!busy}/></label>{!matchesProvider(connection,'feishu')&&<label className="settings-checkbox"><input type="checkbox" checked={!!config.includeAttachments} onChange={e=>changeConfig({includeAttachments:e.target.checked})} disabled={!!busy}/>{t('Include attachments when syncing','同步时包含附件')}</label>}<div className="settings-card-actions"><button className="settings-button" onClick={()=>persist()} disabled={!!busy}>{busy==='save'?t('Saving…','保存中…'):t('Save configuration','保存配置')}</button><button className="settings-button settings-button-primary" onClick={test} disabled={!!busy}>{busy==='test'?t('Testing…','检测中…'):t('Test connection','检测连接')}</button></div></div></details>
    </div><aside className="settings-customize-aside"><section className="settings-panel"><div className="settings-panel-title"><h2>{t('What your twin can do','分身可以做什么')}</h2></div>{[['read','Read messages','读取消息','Needed for everything else','其他功能所必需'],['draft','Draft replies','起草回复','',''],['send','Send replies','发送回复','Follows your Autonomy rules','遵循自主规则'],['react','Add emoji reactions','添加表情回复','',''],['unmentioned','Post where you’re not mentioned','在未被提及的频道发言','','']].map(([key,en,zh,sub,subzh])=><label className="settings-panel-row" key={key}><span className="settings-row-title">{t(en,zh)}{sub&&<span className="settings-subtle">{t(sub,subzh)}</span>}</span><input className="settings-switch" type="checkbox" role="switch" checked={permissions.includes(key)} onChange={e=>changePermission(key,e.target.checked)} disabled={!!busy}/></label>)}</section><section className="settings-card settings-customize-card"><label className="settings-working-hours"><h2>{t('Only act in working hours','仅在工作时间行动')}</h2><input type="checkbox" role="switch" className="settings-switch" checked={!!config.workingHoursOnly} onChange={e=>changeConfig({workingHoursOnly:e.target.checked})} disabled={!!busy}/></label><span className="settings-hint">{t(`${(config.workDays||['Mon','Tue','Wed','Thu','Fri']).join(', ')}, ${config.workFrom||'08:00'} to ${config.workUntil||'19:00'}. Outside these hours your twin reads and drafts, but sends nothing.`,`${(config.workDays||['Mon','Tue','Wed','Thu','Fri']).join('、')}，${config.workFrom||'08:00'} 至 ${config.workUntil||'19:00'}。此范围外仅读取和起草，不发送。`)}</span><button className="settings-button settings-button-small" style={{alignSelf:'flex-start'}} onClick={()=>setModal('hours')} disabled={!!busy}>{t('Edit hours','编辑时间')}</button></section></aside></div>
    {modal==='delete'&&<Modal title={t(`Delete ${displayName}?`,`删除 ${displayName}？`)} onClose={()=>setModal(null)} busy={!!busy}>
      <p>{t('This removes the app from your connections and stops your twin from using it. It does not delete data in the external service.','删除后，此应用将从连接列表移除，分身将无法继续使用它。不会删除外部服务中的数据。')}</p>
      {error&&<div className="settings-error" role="alert">{error}</div>}
      <div className="settings-modal-actions"><button className="settings-button" onClick={()=>setModal(null)} disabled={!!busy}>{t('Cancel','取消')}</button><button className="settings-button settings-button-danger" onClick={deleteApp} disabled={!!busy}>{busy==='delete'?t('Deleting…','删除中…'):t('Confirm deletion','确认删除')}</button></div>
    </Modal>}
    {modal==='disconnect'&&<Modal title={t(`Disconnect ${displayName}?`,`断开${displayName}？`)} onClose={()=>setModal(null)} busy={!!busy}><p>{t('Your twin stops reading and sending in this app. Saved scopes and rules are kept so you can reconnect.','分身将停止读取和发送。配置与规则会保留，便于重新连接。')}</p>{error&&<div className="settings-error">{error}</div>}<div className="settings-modal-actions"><button className="settings-button" onClick={()=>setModal(null)} disabled={!!busy}>{t('Cancel','取消')}</button><button className="settings-button settings-button-danger" onClick={disconnect} disabled={!!busy}>{busy?t('Disconnecting…','断开中…'):t('Disconnect','断开连接')}</button></div></Modal>}
    {['person','word','scope'].includes(modal||'')&&<Modal title={modal==='person'?t('Add important person','添加重要人员'):modal==='word'?t('Add urgent word','添加紧急关键词'):t('Add channel or scope','添加频道或范围')} onClose={()=>setModal(null)}><form onSubmit={addValue} style={{display:'flex',flexDirection:'column',gap:16}}><label className="settings-field">{modal==='word'?t('Word or phrase','关键词或短语'):t('Name','名称')}<input className="settings-input" value={text} onChange={e=>setText(e.target.value)} required/></label>{modal==='person'&&<label className="settings-field">{t('Role','身份')}<select className="settings-select" value={role} onChange={e=>setRole(e.target.value)}><option>VIP</option><option value="Manager">{t('Manager','主管')}</option><option value="Customer">{t('Customer','客户')}</option><option value="Teammate">{t('Teammate','同事')}</option></select></label>}{modal==='scope'&&<label className="settings-field">{t('Handling mode','处理方式')}<select className="settings-select" value={scopeMode} onChange={e=>setScopeMode(e.target.value)}><option value="draft">{t('Draft replies','起草回复')}</option><option value="summary">{t('Summarize only','仅摘要')}</option><option value="deep">{t('Deep Think drafts','深度思考草稿')}</option><option value="send_undo">{t('Send with undo','发送且可撤销')}</option></select></label>}<div className="settings-modal-actions"><button type="button" className="settings-button" onClick={()=>setModal(null)}>{t('Cancel','取消')}</button><button className="settings-button settings-button-primary" type="submit">{t('Add and save','添加并保存')}</button></div></form></Modal>}
    {modal==='hours'&&<Modal title={t('Working hours','工作时间')} onClose={()=>setModal(null)} busy={!!busy}><div className="settings-chip-list">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(day=><label className="settings-checkbox" key={day}><input type="checkbox" checked={(config.workDays||['Mon','Tue','Wed','Thu','Fri']).includes(day)} onChange={e=>{const days=config.workDays||['Mon','Tue','Wed','Thu','Fri'];setConfig({...config,workDays:e.target.checked?[...days,day]:days.filter((d:string)=>d!==day)});setDirty(true);}}/>{day}</label>)}</div><div className="settings-compact-grid"><label className="settings-field">{t('From','开始')}<input type="time" className="settings-input" value={config.workFrom||'08:00'} onChange={e=>{setConfig({...config,workFrom:e.target.value});setDirty(true);}} onInput={e=>{setConfig({...config,workFrom:e.currentTarget.value});setDirty(true);}}/></label><label className="settings-field">{t('Until','结束')}<input type="time" className="settings-input" value={config.workUntil||'19:00'} onChange={e=>{setConfig({...config,workUntil:e.target.value});setDirty(true);}} onInput={e=>{setConfig({...config,workUntil:e.currentTarget.value});setDirty(true);}}/></label></div><label className="settings-field">{t('Timezone','时区')}<input className="settings-input" value={config.timezone||'Asia/Singapore'} onChange={e=>{setConfig({...config,timezone:e.target.value});setDirty(true);}}/></label>{config.workingHoursOnly&&(config.workFrom||'08:00')===(config.workUntil||'19:00')&&<p role="alert">{t('Start and end times must differ.','开始和结束时间不能相同。')}</p>}<div className="settings-modal-actions"><button className="settings-button" onClick={()=>{setConfig(connection.config||{});setDirty(false);setModal(null);}} disabled={!!busy}>{t('Cancel','取消')}</button><button className="settings-button settings-button-primary" onClick={async()=>{if(await persist())setModal(null);}} disabled={!!busy}>{t('Save hours','保存时间')}</button></div></Modal>}
  </main>;
}
